function rowsFor(scene,difficulty,mode,players){if(!Number.isInteger(players)||players<1||players>8)throw Error('Допустимо от 1 до 8 игроков');const row=TABLE[scene+'/'+difficulty+'/'+(g.GrivensburgSessionBalance?.data.legacy && mode==='d10'?'d10':'d20')+'/'+players];return row?clone(row):null;}
function plan(cfg,players,mode){const tag=(cfg||{}).sessionBalance35;if(!tag)return null;const rows=rowsFor(tag.sceneId,tag.difficulty,mode,players);if(!rows)return null;const list=[];rows.forEach(r=>{for(let i=0;i<r.count;i++)list.push(r.key)});return {list,rows,buffRatio:1,elite:false,multiplier:1,balancedProfile:true,profileId:'fix31-shared-dice',playerCount:players,mode:mode==='d20'?'d20':'d10'};}
function enemy(cfg,p,key){const row=p.rows.find(r=>r.key===key);if(!row)throw Error('Нет вида в выбранной встрече: '+key);const src=(g.enemiesDB||{})[key]||(g.customCreaturesDB||{})[key]||{};return {...src,...row,ai:{...(src.ai||{}),...(row.ai||{}),params:{...(src.ai?.params||{}),...(row.ai?.params||{})}},maxHP:row.hp,hp:row.hp,currentHP:row.hp,potionHeal:row.heal??src.potionHeal??0};}
function potionTotals(cfg,p){return Object.fromEntries(p.rows.filter(r=>r.count>0&&r.potions>0).map(r=>[r.key,r.potions]));}
